package in.tutorlink.controller; import in.tutorlink.entity.*; import in.tutorlink.repository.*; import org.springframework.web.bind.annotation.*; import org.springframework.security.core.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/tutors") public class TutorController { final TutorProfileRepository profiles; final UserRepository users; public TutorController(TutorProfileRepository p,UserRepository u){profiles=p;users=u;}
 @GetMapping public List<TutorProfile> all(@RequestParam(required=false) String subject,@RequestParam(required=false) String location){return profiles.findAll().stream().filter(p->subject==null||p.subjects.stream().anyMatch(x->x.equalsIgnoreCase(subject))).filter(p->location==null||p.location.toLowerCase().contains(location.toLowerCase())).toList();}
 @GetMapping("/{id}") public TutorProfile get(@PathVariable Long id){return profiles.findById(id).orElseThrow(()->new NoSuchElementException("Tutor not found"));}
 @GetMapping("/me") public TutorProfile me(@AuthenticationPrincipal Long id){return profiles.findByUserId(id).orElseThrow(()->new NoSuchElementException("Create your tutor profile first"));}
 @PutMapping("/me") public TutorProfile save(@AuthenticationPrincipal Long id,@RequestBody TutorProfile incoming){User u=users.findById(id).orElseThrow();if(u.role!=Role.STUDENT)throw new IllegalArgumentException("Only students can create tutor profiles");TutorProfile p=profiles.findByUserId(id).orElseGet(TutorProfile::new);p.user=u;p.college=incoming.college;p.degree=incoming.degree;p.branch=incoming.branch;p.studyYear=incoming.studyYear;p.location=incoming.location;p.teachingMode=incoming.teachingMode;p.availability=incoming.availability;p.bio=incoming.bio;p.experienceYears=incoming.experienceYears;p.monthlyFee=incoming.monthlyFee;p.subjects=incoming.subjects;p.classes=incoming.classes;p.languages=incoming.languages;return profiles.save(p);}}
